/**
 * Errors surfaced across the FFI boundary (Kotlin exceptions).
 */
sealed class FusionException: kotlin.Exception() {

    /**
     * The recording file could not be opened/read.
     */
    class Io(

        val `msg`: kotlin.String
        ) : FusionException() {
        override val message
            get() = "msg=${ `msg` }"
    }

    /**
     * The recording could not be interpreted at all.
     */
    class Parse(

        val `msg`: kotlin.String
        ) : FusionException() {
        override val message
            get() = "msg=${ `msg` }"
    }

    /**
     * The recording parsed but contains no samples to analyze.
     */
    class EmptyRecording(

        val `msg`: kotlin.String
        ) : FusionException() {
        override val message
            get() = "msg=${ `msg` }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FusionException> {
        override fun lift(error_buf: RustBuffer.ByValue): FusionException = FfiConverterTypeFusionError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeFusionError : FfiConverterRustBuffer<FusionException> {
    override fun read(buf: ByteBuffer): FusionException {


        return when(buf.getInt()) {
            1 -> FusionException.Io(
                FfiConverterString.read(buf),
                )
            2 -> FusionException.Parse(
                FfiConverterString.read(buf),
                )
            3 -> FusionException.EmptyRecording(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FusionException): ULong {
        return when(value) {
            is FusionException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is FusionException.Parse -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is FusionException.EmptyRecording -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: FusionException, buf: ByteBuffer) {
        when(value) {
            is FusionException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is FusionException.Parse -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is FusionException.EmptyRecording -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Errors specific to authoring and matching segments.
 */
sealed class SegmentException: kotlin.Exception() {

    /**
     * The requested start/finish selection cannot describe a segment.
     */
    class InvalidSelection(

        val `msg`: kotlin.String
        ) : SegmentException() {
        override val message
            get() = "msg=${ `msg` }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SegmentException> {
        override fun lift(error_buf: RustBuffer.ByValue): SegmentException = FfiConverterTypeSegmentError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeSegmentError : FfiConverterRustBuffer<SegmentException> {
    override fun read(buf: ByteBuffer): SegmentException {


        return when(buf.getInt()) {
            1 -> SegmentException.InvalidSelection(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SegmentException): ULong {
        return when(value) {
            is SegmentException.InvalidSelection -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: SegmentException, buf: ByteBuffer) {
        when(value) {
            is SegmentException.InvalidSelection -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




